package com.byawasaya.platform.business;
import java.math.BigDecimal; import java.time.Instant; import java.util.List; import java.util.UUID;
import com.byawasaya.platform.catalog.CatalogDtos;
import jakarta.validation.constraints.DecimalMin; import jakarta.validation.constraints.Max; import jakarta.validation.constraints.Min; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Pattern; import jakarta.validation.constraints.Size;
public final class StoreDtos {
 private StoreDtos(){}
 public record StoreResponse(UUID id,String name,String slug,String tenantTag,String ownerName,String ownerEmail,String phone,String logoUrl,String description,String plan,BusinessStatus status,String templateKey,String primaryColor,boolean codEnabled,boolean onlinePaymentEnabled,int advancePaymentPercent,BigDecimal deliveryFee,BigDecimal minimumOrderAmount,Instant createdAt){public static StoreResponse from(Business b){return new StoreResponse(b.getId(),b.getName(),b.getSlug(),b.getTenantTag(),b.getOwnerName(),b.getOwnerEmail(),b.getPhone(),b.getLogoAssetId()==null?null:"/api/store/"+b.getSlug()+"/assets/"+b.getLogoAssetId(),b.getDescription(),b.getPlanCode(),b.getStatus(),b.getTemplateKey(),b.getPrimaryColor(),b.isCodEnabled(),b.isOnlinePaymentEnabled(),b.getAdvancePaymentPercent(),b.getDeliveryFee(),b.getMinimumOrderAmount(),b.getCreatedAt());}}
 public record PublicStoreResponse(String name,String slug,String description,String phone,String logoUrl,String templateKey,String primaryColor,boolean codEnabled,boolean onlinePaymentEnabled,int advancePaymentPercent,BigDecimal deliveryFee,BigDecimal minimumOrderAmount,List<String> paymentProviders,List<CatalogDtos.ProductResponse> products){public static PublicStoreResponse from(Business b,List<CatalogDtos.ProductResponse> products,List<String> paymentProviders){return new PublicStoreResponse(b.getName(),b.getSlug(),b.getDescription(),b.getPhone(),b.getLogoAssetId()==null?null:"/api/store/"+b.getSlug()+"/assets/"+b.getLogoAssetId(),b.getTemplateKey(),b.getPrimaryColor(),b.isCodEnabled(),b.isOnlinePaymentEnabled(),b.getAdvancePaymentPercent(),b.getDeliveryFee(),b.getMinimumOrderAmount(),paymentProviders,products);}}
 public record UpdateSettingsRequest(@NotBlank @Size(max=120) String name,@Size(max=30) String phone,@Size(max=1000) String description,@NotBlank String templateKey,@NotBlank @Pattern(regexp="#[0-9a-fA-F]{6}", message="Use a six-digit hex colour.") @Size(max=20) String primaryColor,boolean codEnabled,boolean onlinePaymentEnabled,@Min(0) @Max(100) int advancePaymentPercent,@DecimalMin("0.00") BigDecimal deliveryFee,@DecimalMin("0.00") BigDecimal minimumOrderAmount){}
}
